
import { Link } from 'react-router-dom';

export interface BreadcrumbItem {
  label: string;
  to?: string;
}

interface BreadcrumbProps {
  items: BreadcrumbItem[];
}

export default function Breadcrumb({ items }: BreadcrumbProps) {
  return (
    <div className="max-w-[1400px] mx-auto px-6 py-3">
      <nav className="flex items-center gap-2 text-xs text-gray-500 flex-wrap">
        <Link to="/" className="hover:text-red-600 cursor-pointer">
          トップ
        </Link>
        {items.map((item, idx) => (
          <span key={idx} className="flex items-center gap-2">
            <i className="ri-arrow-right-s-line w-3 h-3 flex items-center justify-center"></i>
            {item.to ? (
              <Link to={item.to} className="hover:text-red-600 cursor-pointer">
                {item.label}
              </Link>
            ) : (
              <span className={idx === items.length - 1 ? 'text-gray-800 font-bold' : 'text-gray-500'}>
                {item.label}
              </span>
            )}
          </span>
        ))}
      </nav>
    </div>
  );
}
